private static roundTo(amount: number, currency: string): number {
  const decimals = CURRENCY_DECIMALS[currency] ?? 2;
  const factor = 10 ** decimals;
  // Round half away from zero to avoid banker's surprises and float drift.
  return Math.sign(amount) * Math.round(Math.abs(amount) * factor + Number.EPSILON) / factor;
